-- Serialize PIN attempts; stale/concurrent verification cannot bypass lockout.
create function public.record_pin_attempt(target_parent uuid, success boolean) returns boolean language plpgsql security definer set search_path='' as $$
declare s public.parent_secrets;
begin
 select * into s from public.parent_secrets where parent_id=target_parent for update;
 if not found or s.locked_until>now() then return false; end if;
 if success then update public.parent_secrets set failed_attempts=0,locked_until=null where parent_id=target_parent; return true; end if;
 if s.locked_until is not null then s.failed_attempts:=0; end if;
 update public.parent_secrets set failed_attempts=s.failed_attempts+1, locked_until=case when s.failed_attempts+1>=5 then now()+interval '15 minutes' else null end where parent_id=target_parent;
 return false;
end; $$;
revoke all on function public.record_pin_attempt(uuid,boolean) from public,anon,authenticated;
grant execute on function public.record_pin_attempt(uuid,boolean) to service_role;
